import { loadFont as loadBarlow } from "@remotion/google-fonts/BarlowCondensed";
import { loadFont as loadPlex } from "@remotion/google-fonts/IBMPlexSans";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// FÊNIX SERVIÇOS (cliente "click soluções", 20/11) — portaria, controle de acesso, monitoramento, serviços gerais e
// limpeza em Carajás/Parauapebas/Curionópolis. Jeito motion: só veio o logo (as fotos do site não foram baixadas), então
// o vídeo é tipografia, ícones desenhados e o logo. Identidade do logo e do site: azul-marinho #01122E, vermelho #FE0115
// e branco; título condensado pesado em caixa-alta (Barlow Condensed, como o "NADA FORA DE CONTROLE." do site) e texto em
// IBM Plex Sans. v2 (correção da Nina): linhas largas quebradas em duas e câmera contida, todo texto em x 120–940 /
// y 250–1480. v3: vídeo de câmera de frota do cliente (sem som) em 16,9–19,02 s, "Câmeras para frotas". Tom sério, de segurança. Copy só com o que está no site. Tempos = voz src/voz-v1-cortada.wav (o locutor).

const { fontFamily: BC } = loadBarlow("normal", { weights: ["700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: PLEX } = loadPlex("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const FX3_FPS = 30;
const END = 39.8;
export const FX3_FRAMES = Math.round(END * FX3_FPS);
const NAVY = "#01122E";
const NAVY2 = "#06204F";
const RED = "#F2101F";
const DRED = "#7A0710";
const WHITE = "#FFFFFF";
const PAPER = "#F2F4F8";
const MUTE = "#9FB0CC";
const COL = 840;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.25));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const hd = (size: number, color = WHITE): React.CSSProperties => ({ fontFamily: BC, fontWeight: 800, fontSize: size, lineHeight: 0.95, color, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "0.005em" });
const slam = (t: number, at: number, d = 0.28): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.6 - 0.6 * e).toFixed(3)})` };
};

const Row: React.FC<{ top: number; children: React.ReactNode; gap?: number; style?: React.CSSProperties }> = ({ top, children, gap = 0, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", justifyContent: "center", alignItems: "center", gap, ...style }}>{children}</div>
);
// entra subindo de trás de uma linha (máscara) e para
const Line: React.FC<{ t: number; at: number; w: string; size: number; color?: string; font?: "hd" | "plex" }> = ({ t, at, w, size, color = WHITE, font = "hd" }) => {
  const e = k(t, at, 0.42);
  const st: React.CSSProperties = font === "hd" ? hd(size, color) : { fontFamily: PLEX, fontWeight: 600, fontSize: size, lineHeight: 1.1, color, whiteSpace: "nowrap" };
  return (
    <div style={{ overflow: "hidden", padding: "4px 12px 10px" }}>
      <div style={{ ...st, transform: `translateY(${((1 - e) * 115).toFixed(1)}%)` }}>{w}</div>
    </div>
  );
};
// palavra-chave numa tarja vermelha que se abre da esquerda
const Tag: React.FC<{ t: number; at: number; w: string; size: number; bg?: string; fg?: string }> = ({ t, at, w, size, bg = RED, fg = WHITE }) => (
  <div style={{ background: bg, padding: `${size * 0.1}px ${size * 0.3}px ${size * 0.14}px`, transform: `scaleX(${k(t, at, 0.4).toFixed(3)})`, transformOrigin: "0 50%", boxShadow: "0 18px 40px rgba(0,0,0,0.35)" }}>
    <div style={{ ...hd(size, fg), opacity: interpolate(t, [at + 0.1, at + 0.34], [0, 1], { ...cl, easing: OUT }) }}>{w}</div>
  </div>
);
const fit = (w: string, max: number, col = COL) => Math.min(max, Math.floor(col / (w.length * 0.47)));

// ───────── fundos lisos ─────────
type Bg = "navy" | "deep" | "red" | "paper";
const BgFill: React.FC<{ bg: Bg }> = ({ bg }) => (
  <AbsoluteFill
    style={{
      background:
        bg === "navy" ? `radial-gradient(ellipse 95% 65% at 50% 42%, ${NAVY2} 0%, ${NAVY} 72%)`
        : bg === "deep" ? "radial-gradient(ellipse 90% 60% at 50% 45%, #0A1B3A 0%, #000814 78%)"
        : bg === "red" ? `linear-gradient(165deg, #FF2A36 0%, ${RED} 45%, #A00512 100%)`
        : `radial-gradient(ellipse 90% 60% at 50% 40%, #FFFFFF 0%, ${PAPER} 62%, #DCE2EC 100%)`,
    }}
  />
);
type Cam = "in" | "out" | "left" | "right" | "tilt" | "rise";
const MScene: React.FC<{ t: number; a: number; b: number; bg: Bg; cam: Cam; dy?: number; children: React.ReactNode }> = ({ t, a, b, bg, cam, dy = 0, children }) => {
  if (t < a || t >= b) return null;
  const e = interpolate(lin(t, a, b), [0, 1], [0, 1], { easing: Easing.inOut(Easing.sin) });
  const enter = 1 - k(t, a, 0.5); // a cena já entra em movimento
  const tr =
    cam === "in" ? `scale(${(1 + 0.03 * e + 0.03 * enter).toFixed(4)})`
    : cam === "out" ? `scale(${(1.04 - 0.04 * e).toFixed(4)})`
    : cam === "left" ? `translateX(${(16 - 32 * e + 30 * enter).toFixed(1)}px) scale(1.01)`
    : cam === "right" ? `translateX(${(-16 + 32 * e - 30 * enter).toFixed(1)}px) scale(${(1.0 + 0.025 * e).toFixed(4)})`
    : cam === "tilt" ? `rotate(${(-0.8 + 1.6 * e).toFixed(2)}deg) scale(${(1.01 + 0.02 * e).toFixed(4)})`
    : `translateY(${(50 - 70 * e + 90 * enter).toFixed(1)}px)`;
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <BgFill bg={bg} />
      <AbsoluteFill style={{ transform: tr, transformOrigin: "50% 50%" }}><AbsoluteFill style={{ transform: `translateY(${dy}px)` }}>{children}</AbsoluteFill></AbsoluteFill>
    </AbsoluteFill>
  );
};

// cenas (inícios e fins em segundos da voz)
const S = { s1: [0, 2.38], s2: [2.38, 5.4], s3: [5.4, 8.08], s4: [8.08, 10.76], s5: [10.76, 14.4], s6: [14.4, 21.0], frota: [16.9, 19.02], s7: [21.0, 24.75], s8: [24.75, 28.2], s9: [28.2, 32.9], s10: [32.9, END] } as const;

// ───────── ícones (traço) ─────────
const ICO = { stroke: WHITE, strokeWidth: 1.7, fill: "none", strokeLinecap: "round", strokeLinejoin: "round" } as const;
const IconGuard = () => (<g {...ICO}><path d="M7 8.2h10M8 8.2c0-2.6 1.8-4.2 4-4.2s4 1.6 4 4.2" /><path d="M8.6 9.6a3.4 3.4 0 0 0 6.8 0" /><path d="M5 21c.4-3.8 3.2-6 7-6s6.6 2.2 7 6" /><path d="M12 15v3" /></g>);
const IconGate = () => (<g {...ICO}><rect x="3" y="9" width="4" height="12" rx="1" /><path d="M7 12h14" /><path d="M10 12l2 2.5M14 12l2 2.5M18 12l2 2.5" /><path d="M3 21h18" /></g>);
const IconCam = () => (<g {...ICO}><path d="M3.5 7.5l13 3.4-1.4 5.2-13-3.4z" /><path d="M16.5 10.9l3.6-1.6-1.4 5.2-2.8-1" /><path d="M7.5 14l-1 4.5H3.5" /></g>);
const IconGear = () => (<g {...ICO}><circle cx="12" cy="12" r="3" /><path d="M12 3v2.4M12 18.6V21M3 12h2.4M18.6 12H21M5.6 5.6l1.7 1.7M16.7 16.7l1.7 1.7M5.6 18.4l1.7-1.7M16.7 7.3l1.7-1.7" /><circle cx="12" cy="12" r="6.2" /></g>);
const IconClean = () => (<g {...ICO}><path d="M9 9h5l1.5 3v8.5a.5.5 0 0 1-.5.5H8a.5.5 0 0 1-.5-.5V12z" /><path d="M10 9V6h3v3M13 6h4l1 1.5" /><path d="M19.5 4.5l1-1M20.5 7h1.3M19.5 9.5l1 1" /></g>);
const IconPin = ({ c = RED }: { c?: string }) => (<g><path d="M12 22s7-6.6 7-12a7 7 0 0 0-14 0c0 5.4 7 12 7 12z" fill={c} /><circle cx="12" cy="10" r="2.7" fill={WHITE} /></g>);

// ───────── 0–2.38: NA PORTARIA, / NINGUÉM CONFERE. (cancela aberta, balançando à toa) ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = S.s1;
  const up = k(t, 0.05, 0.6);
  const swing = -62 * up + Math.sin(t * 3.2) * 6 * up;
  return (
    <MScene t={t} a={a} b={b} bg="navy" cam="in" dy={150}>
      <div style={{ position: "absolute", left: 540 - 240, top: 90, width: 480, height: 496, opacity: k(t, 0, 0.25) }}>
        <svg width={480} height={496} viewBox="0 -100 600 620">
          <rect x={110} y={250} width={80} height={250} rx={10} fill={NAVY2} stroke={WHITE} strokeWidth={6} />
          <circle cx={150} cy={300} r={16} fill={RED} />
          <g transform={`rotate(${swing.toFixed(2)} 150 300)`}>
            <rect x={150} y={286} width={400} height={28} rx={14} fill={WHITE} />
            {[0, 1, 2, 3].map((i) => <rect key={i} x={200 + i * 90} y={286} width={42} height={28} fill={RED} />)}
          </g>
          <rect x={60} y={496} width={480} height={8} rx={4} fill={MUTE} opacity={0.5} />
        </svg>
      </div>
      <Row top={610}><div style={slam(t, 0.05, 0.24)}><div style={hd(150)}>Na</div></div></Row>
      <Row top={750}><div style={slam(t, 0.22, 0.24)}><div style={hd(150)}>portaria,</div></div></Row>
      <Row top={915}><Tag t={t} at={1.37} w="Ninguém" size={118} /></Row>
      <Row top={1065}><Tag t={t} at={1.5} w="confere." size={118} /></Row>
    </MScene>
  );
};

// ───────── 2.38–5.4: A CÂMERA GRAVA… / E NINGUÉM OLHA. ─────────
const S2: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = S.s2;
  const inn = pop(t, a + 0.02, 0.5);
  const pan = Math.sin((t - a) * 1.4) * 14;
  const rec = Math.floor((t - a) * 2.2) % 2 === 0;
  const off = k(t, 4.21, 0.35); // em "ninguém olha" o monitor apaga
  return (
    <MScene t={t} a={a} b={b} bg="deep" cam="left" dy={140}>
      <div style={{ position: "absolute", left: 540 - 330, top: 100, width: 660, height: 600, transform: `scale(${inn.toFixed(3)})` }}>
        <svg width={660} height={600} viewBox="0 0 660 600">
          {/* campo de visão da câmera */}
          <path d={`M330 210 L${120 + pan * 4} 590 L${540 + pan * 4} 590 Z`} fill={WHITE} opacity={0.06} />
          <rect x={300} y={40} width={60} height={80} rx={8} fill={NAVY2} stroke={WHITE} strokeWidth={6} />
          <g transform={`rotate(${(18 + pan).toFixed(2)} 330 120)`}>
            <rect x={170} y={110} width={320} height={130} rx={22} fill={WHITE} />
            <rect x={140} y={130} width={50} height={90} rx={10} fill={MUTE} />
            <circle cx={200} cy={175} r={40} fill={NAVY} />
            <circle cx={200} cy={175} r={20} fill="#132C5E" />
            <circle cx={440} cy={150} r={13} fill={rec ? RED : "#5A0A10"} />
          </g>
        </svg>
        <div style={{ position: "absolute", left: 470, top: 22, fontFamily: PLEX, fontWeight: 600, fontSize: 34, color: rec ? RED : "#5A0A10", letterSpacing: "0.12em" }}>REC</div>
      </div>
      {/* monitor sem ninguém olhando */}
      <div style={{ position: "absolute", left: 540 - 160, top: 560, width: 320, height: 120, borderRadius: 14, border: `5px solid ${MUTE}`, background: `rgba(159,176,204,${(0.18 * (1 - off)).toFixed(3)})`, opacity: k(t, 2.9, 0.4) }} />
      <Row top={720}><Line t={t} at={2.61} w="A câmera" size={110} /></Row>
      <Row top={835}><Line t={t} at={2.95} w="grava…" size={110} /></Row>
      <Row top={975}><Tag t={t} at={4.21} w="E ninguém" size={110} /></Row>
      <Row top={1110}><Tag t={t} at={4.36} w="olha." size={110} /></Row>
    </MScene>
  );
};

// ───────── 5.4–8.08: NA ESTRADA, / O VEÍCULO SOME. ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = S.s3;
  const go = interpolate(t, [a, 7.5], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
  const gone = lin(t, 6.5, 7.3);
  const dash = ((t - a) * 260) % 120;
  const q = pop(t, 7.25, 0.45);
  return (
    <MScene t={t} a={a} b={b} bg="navy" cam="rise" dy={150}>
      <svg style={{ position: "absolute", left: 0, top: 260 }} width={1080} height={700} viewBox="0 0 1080 700">
        <path d="M470 20 L610 20 L1000 700 L80 700 Z" fill="#0B2552" />
        <path d="M470 20 L80 700 M610 20 L1000 700" stroke={MUTE} strokeWidth={6} />
        <path d="M540 20 L540 700" stroke={WHITE} strokeWidth={10} strokeDasharray="60 60" strokeDashoffset={-dash} opacity={0.8} />
      </svg>
      {/* o caminhão se afasta e some */}
      <div style={{ position: "absolute", left: 540 - 170, top: 640 - 330 * go, width: 340, height: 220, transform: `scale(${(1 - 0.78 * go).toFixed(3)})`, transformOrigin: "50% 100%", opacity: 1 - gone }}>
        <svg width={340} height={220} viewBox="0 0 340 220">
          <rect x={20} y={30} width={300} height={150} rx={16} fill={WHITE} />
          <rect x={20} y={150} width={300} height={14} fill={RED} />
          <circle cx={80} cy={190} r={24} fill={NAVY} stroke={WHITE} strokeWidth={6} />
          <circle cx={260} cy={190} r={24} fill={NAVY} stroke={WHITE} strokeWidth={6} />
        </svg>
      </div>
      {/* pino de GPS sem sinal */}
      <div style={{ position: "absolute", left: 540 - 70, top: 250, width: 140, height: 140, transform: `scale(${q.toFixed(3)})`, transformOrigin: "50% 100%" }}>
        <svg width={140} height={140} viewBox="0 0 24 24"><IconPin /></svg>
        <div style={{ position: "absolute", left: 0, right: 0, top: 22, textAlign: "center", ...hd(56, RED) }}>?</div>
      </div>
      <Row top={1010}><div style={slam(t, 5.62, 0.24)}><div style={hd(140)}>Na estrada,</div></div></Row>
      <Row top={1190}><Tag t={t} at={6.08} w="o veículo some." size={118} /></Row>
    </MScene>
  );
};

// ───────── 8.08–10.76: E QUANDO PERCEBEM… / JÁ PASSOU. (relógio disparado) ─────────
const S4: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = S.s4;
  const spin = interpolate(t, [a, 9.95], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  const stop = k(t, 9.98, 0.3);
  const ang = spin * 1440 + stop * 20;
  return (
    <MScene t={t} a={a} b={b} bg="red" cam="out" dy={160}>
      <div style={{ position: "absolute", left: 540 - 230, top: 140, width: 460, height: 460, transform: `scale(${pop(t, a + 0.02, 0.5).toFixed(3)})` }}>
        <svg width={460} height={460} viewBox="0 0 460 460">
          <circle cx={230} cy={230} r={200} fill={WHITE} />
          <circle cx={230} cy={230} r={200} fill="none" stroke={DRED} strokeWidth={14} />
          {Array.from({ length: 12 }).map((_, i) => (
            <rect key={i} x={226} y={50} width={8} height={i % 3 === 0 ? 34 : 18} rx={4} fill={NAVY} transform={`rotate(${i * 30} 230 230)`} />
          ))}
          <rect x={222} y={130} width={16} height={110} rx={8} fill={NAVY} transform={`rotate(${(ang / 12).toFixed(2)} 230 230)`} />
          <rect x={226} y={80} width={8} height={160} rx={4} fill={RED} transform={`rotate(${ang.toFixed(2)} 230 230)`} />
          <circle cx={230} cy={230} r={16} fill={NAVY} />
        </svg>
      </div>
      <Row top={650}><Line t={t} at={8.44} w="E quando" size={104} /></Row>
      <Row top={765}><Line t={t} at={8.75} w="percebem…" size={104} /></Row>
      <Row top={915}><div style={slam(t, 9.98, 0.26)}><div style={{ background: WHITE, padding: "14px 46px 22px", boxShadow: `0 22px 50px rgba(0,0,0,0.35)` }}><div style={hd(170, RED)}>Já passou.</div></div></div></Row>
    </MScene>
  );
};

// ───────── 10.76–14.4: logo / NADA FORA DE CONTROLE. ─────────
const S5: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = S.s5;
  const e = pop(t, 10.92, 0.6);
  return (
    <MScene t={t} a={a} b={b} bg="navy" cam="in" dy={130}>
      <Row top={170} style={{ opacity: Math.min(1, e * 2), transform: `scale(${(0.6 + 0.4 * e).toFixed(3)})` }}>
        <Img src={staticFile("click-solucoes/logo.png")} style={{ width: 460, display: "block", filter: "drop-shadow(0 24px 50px rgba(0,0,0,0.45))" }} />
      </Row>
      <Row top={690}><Line t={t} at={12.46} w="Nada" size={150} /></Row>
      <Row top={845}><Line t={t} at={12.75} w="fora de" size={150} /></Row>
      <Row top={1000}><Line t={t} at={13.08} w="controle." size={150} color={RED} /></Row>
    </MScene>
  );
};

// ───────── 14.4–21.0: os cinco serviços, um por fala ─────────
const SERV: { at: number; w: string; sub?: string; icon: () => JSX.Element }[] = [
  { at: 14.68, w: "Portaria", icon: IconGuard },
  { at: 15.35, w: "Controle de acesso", icon: IconGate },
  { at: 16.52, w: "Câmeras e GPS", sub: "Monitoramento", icon: IconCam },
  { at: 19.09, w: "Serviços gerais", icon: IconGear },
  { at: 20.26, w: "Limpeza", icon: IconClean },
];
const S6: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = S.s6;
  const RH = 160, GAP = 26, TOP = 600;
  // câmera estilo Screen Studio: segue o serviço que está sendo falado, sem ir e voltar
  const idx = SERV.filter((s) => t >= s.at).length;
  const focus = SERV.reduce((acc, s, i) => acc + (i === 0 ? 0 : k(t, s.at - 0.1, 0.6) * (RH + GAP)), 0);
  const camY = -0.1 * focus;
  const gps = pop(t, 18.14, 0.4);
  return (
    <MScene t={t} a={a} b={b} bg="navy" cam="in">
      <AbsoluteFill style={{ transform: `translateY(${(camY + 60).toFixed(1)}px)` }}>
        <Row top={TOP - 150}><Line t={t} at={a + 0.05} w="Fênix Serviços" size={64} color={MUTE} font="plex" /></Row>
        {SERV.map((s, i) => {
          const e = k(t, s.at, 0.45);
          const on = i === idx - 1;
          return (
            <div key={i} style={{ position: "absolute", left: 120, width: COL, top: TOP + i * (RH + GAP), height: RH, borderRadius: 26, background: on ? WHITE : "rgba(255,255,255,0.08)", border: on ? "none" : "2px solid rgba(255,255,255,0.18)", display: "flex", alignItems: "center", gap: 34, padding: "0 36px", boxSizing: "border-box", opacity: Math.min(1, e * 2), transform: `translateX(${((1 - e) * 140).toFixed(1)}px)`, boxShadow: on ? "0 24px 50px rgba(0,0,0,0.4)" : "none" }}>
              <div style={{ position: "relative", width: 104, height: 104, borderRadius: 22, background: RED, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, s.at + 0.05, 0.4).toFixed(3)})` }}>
                <svg width={70} height={70} viewBox="0 0 24 24"><s.icon /></svg>
                {i === 2 ? (
                  <div style={{ position: "absolute", right: -26, top: -26, width: 60, height: 60, transform: `scale(${gps.toFixed(3)})`, transformOrigin: "50% 100%" }}>
                    <svg width={60} height={60} viewBox="0 0 24 24"><IconPin c={on ? NAVY : WHITE} /></svg>
                  </div>
                ) : null}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                {s.sub ? <div style={{ fontFamily: PLEX, fontWeight: 600, fontSize: 30, color: on ? RED : MUTE, letterSpacing: "0.08em", textTransform: "uppercase" }}>{s.sub}</div> : null}
                <div style={hd(s.w.length > 14 ? 78 : 88, on ? NAVY : WHITE)}>{s.w}</div>
              </div>
            </div>
          );
        })}
      </AbsoluteFill>
    </MScene>
  );
};

// ───────── 16.9–19.02: CÂMERAS PARA FROTAS (vídeo do cliente, sem som, numa tela de monitor) ─────────
const Frota: React.FC<{ t: number }> = ({ t }) => {
  const [a, b] = S.frota;
  const W = 760, H = Math.round(760 * 656 / 576);
  const inn = k(t, a, 0.5);
  const z = 1.02 + 0.08 * lin(t, a, b);
  return (
    <MScene t={t} a={a} b={b} bg="navy" cam="in">
