// ───────── trocas: nunca a mesma duas vezes seguidas ─────────
type TK = "iris" | "flash" | "stripe" | "split";
const TR: [number, TK, string][] = [
  [2.38, "stripe", RED], [5.4, "split", NAVY], [8.08, "iris", RED], [10.76, "stripe", NAVY], [14.4, "flash", WHITE], [16.9, "stripe", RED], [19.02, "flash", WHITE],
  [21.0, "split", NAVY2], [24.75, "iris", PAPER], [28.2, "stripe", RED], [32.9, "flash", WHITE],
];
const Trans: React.FC<{ t: number; at: number; kind: TK; c: string; i: number }> = ({ t, at, kind, c, i }) => {
  const d = 0.2;
  if (t < at - d || t > at + d + 0.1) return null;
  if (kind === "flash") {
    if (t < at) return null;
    return <AbsoluteFill style={{ background: c, opacity: 0.8 * (1 - lin(t, at, at + 0.26)) }} />;
  }
  if (kind === "iris") {
    // a cor da cena seguinte nasce no centro e cobre a tela
    return t < at ? <div style={{ position: "absolute", left: 540 - 1300, top: 960 - 1300, width: 2600, height: 2600, borderRadius: 1300, background: c, transform: `scale(${interpolate(t, [at - d, at], [0, 1], { ...cl, easing: Easing.in(Easing.quad) }).toFixed(4)})` }} /> : null;
  }
  if (kind === "split") {
    const v = t < at ? interpolate(t, [at - d, at], [0, 1], { ...cl, easing: OUT }) : 1 - interpolate(t, [at, at + d], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
    return (
      <>
        <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 962, background: c, borderBottom: `10px solid ${RED}`, boxSizing: "border-box", transform: `translateY(${((v - 1) * 980).toFixed(0)}px)` }} />
        <div style={{ position: "absolute", left: 0, top: 958, width: 1080, height: 962, background: c, borderTop: `10px solid ${RED}`, boxSizing: "border-box", transform: `translateY(${((1 - v) * 980).toFixed(0)}px)` }} />
      </>
    );
  }
  const dir = i % 2 ? -1 : 1;
  const x = (lin(t, at - d, at + d) * 2 - 1) * 2100 * dir;
  return <div style={{ position: "absolute", left: 540 - 800, top: -300, width: 1600, height: 2520, transform: `translateX(${x.toFixed(0)}px) skewX(${-14 * dir}deg)`, background: c, boxShadow: `${100 * dir}px 0 0 ${WHITE}, ${-100 * dir}px 0 0 ${c === RED ? NAVY : RED}` }} />;
};

